package io.testhub.platform;

import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import io.testhub.platform.account.PlatformUserPrincipal;
import io.testhub.platform.functional.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.github.f4b6a3.ulid.UlidCreator;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.MediaType;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;

class P2D08D07PlanTests extends P1FlowTestSupport {
    @Autowired FunctionalAssetService assets;
    @Autowired FunctionalTestExecutionService executions;
    @Autowired FunctionalTransferService transfer;
    @Autowired FunctionalHistorySyncService sync;
    @Autowired org.springframework.transaction.PlatformTransactionManager transactions;
    record F(PlatformUserPrincipal actor,String project,FunctionalCase testcase,FunctionalTestPlan plan) { }
    F fixture(){var a=actor();var p=project(a);var c=assets.createCatalog(a,p,new FunctionalAssetService.CatalogInput("cases",null,0,"CASES"));var tc=assets.createCase(a,p,new FunctionalAssetService.CaseInput(c.id(),null,"CASE-1","标题A","P1","READY","FUNCTIONAL","","步骤A","结果"));var plan=executions.createPlan(a,p,new FunctionalTestExecutionService.PlanInput(null,"PLAN-1","计划","READY","",List.of(tc.id())));return new F(a,p,tc,plan);}
    F empty(){var a=actor();return new F(a,project(a),null,null);}
    void rename(F f){var c=f.testcase;assets.updateCase(f.actor,f.project,c.id(),new FunctionalAssetService.CaseInput(c.catalogId(),null,c.caseCode(),"标题B",c.priority(),c.status(),c.caseType(),c.precondition(),"步骤B",c.expectedResult()));}
    FunctionalTestRun run(F f){return executions.createRun(f.actor,f.project,f.plan.id(),"QA批次");}
    FunctionalTestRunCase result(F f,FunctionalTestRun r){return executions.listRunCases(f.actor,f.project,r.id()).getFirst();}
    String url(F f){return "/api/v1/projects/"+f.project+"/functional/plans/"+f.plan.id();}
    Map<String,Long> counts(){var m=new LinkedHashMap<String,Long>();for(String t:List.of("functional_test_plan","functional_test_plan_case","functional_test_run","functional_test_run_case","functional_test_run_step","functional_transfer_receipt","functional_history_sync_receipt","audit_log"))m.put(t,jdbc.sql("SELECT COUNT(*) FROM "+t).query(Long.class).single());return m;}
    int update(F f,String code)throws Exception {return mvc.perform(put(url(f)).with(user(f.actor)).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"planCode\":"+code+",\"name\":\"改名\",\"status\":\"READY\",\"description\":\"\",\"caseIds\":[]}")).andReturn().getResponse().getStatus();}
    FunctionalHistorySyncService.Request request(F f,FunctionalHistorySyncService.Item i){return new FunctionalHistorySyncService.Request(UUID.randomUUID().toString(),f.actor.userId(),sync.snapshot(f.actor,f.project,f.actor.userId()).revision(),List.of(new FunctionalHistorySyncService.Operation(UUID.randomUUID().toString(),i,java.time.Instant.parse("2026-10-10T10:00:00.120Z"))));}
    @Test void B01_equivalentCodeUpdates()throws Exception {var f=fixture();var r=run(f);for(String c:List.of("\"PLAN-1\"","\" plan-1 \"")){assertEquals(200,update(f,c));assertEquals("PLAN-1",executions.getPlan(f.actor,f.project,f.plan.id()).planCode());assertEquals(r.id(),executions.listRuns(f.actor,f.project,f.plan.id()).getFirst().id());}}
    @Test void B02_differentCodeAtomic()throws Exception {var f=fixture();var before=counts();var members=executions.listPlanCases(f.actor,f.project,f.plan.id());assertEquals(400,update(f,"\"OTHER-1\""));assertEquals(f.plan,executions.getPlan(f.actor,f.project,f.plan.id()));assertEquals(members,executions.listPlanCases(f.actor,f.project,f.plan.id()));assertEquals(before,counts());}
    @Test void B03_invalidCodes()throws Exception {var f=fixture();for(String c:List.of("null","\"\"","\"   \"","\"!bad\"")){var before=counts();assertEquals(400,update(f,c));assertEquals(before,counts());}var before=counts();assertEquals(400,mvc.perform(put(url(f)).with(user(f.actor)).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"x\"}")).andReturn().getResponse().getStatus());assertEquals(before,counts());}
    @Test void B04_newRunFreezesTitleAndSteps(){var f=fixture();var r=run(f);rename(f);assertEquals("标题A",result(f,r).title());assertEquals("SNAPSHOT",json.valueToTree(result(f,r)).path("titleSource").asText());assertEquals("步骤A",executions.listRunSteps(f.actor,f.project,result(f,r).id()).getFirst().stepText());assertEquals("标题B",result(f,run(f)).title());}
    @Test void B05_legacyMissingIsExplicit(){var f=fixture();var r=run(f);jdbc.sql("DELETE FROM functional_test_run_case WHERE run_id=:r").param("r",r.id()).update();var old=UlidCreator.getUlid().toString();jdbc.sql("INSERT INTO functional_test_run_case(id,run_id,case_id,status,note) VALUES(:i,:r,:c,'NOT_RUN','')").param("i",old).param("r",r.id()).param("c",f.testcase.id()).update();rename(f);var row=executions.listRunCases(f.actor,f.project,r.id()).stream().filter(c->c.id().equals(old)).findFirst().orElseThrow();assertEquals("标题B",row.title());assertEquals("CURRENT_ASSET",json.valueToTree(row).path("titleSource").asText());}
    @Test void B06_transferPreservesSnapshotAndMissing()throws Exception {var a=fixture();run(a);rename(a);var route="/api/v1/projects/"+a.project+"/functional/transfer";
        assertEquals(400,mvc.perform(get(route).with(user(a.actor)).param("version","6").param("includeGovernance","false").param("includeDefects","false").param("includeFiles","false")).andReturn().getResponse().getStatus());
        var http=mvc.perform(get(route).with(user(a.actor)).param("version","6").param("includeGovernance","false").param("includeDefects","false").param("includeFiles","false").param("titleSnapshots","true")).andReturn().getResponse();assertEquals(200,http.getStatus());assertTrue(http.getContentAsString().contains("标题A"));
        var snapshot=transfer.export(a.actor,a.project,6,true,false,false,false,true);var node=json.valueToTree(snapshot);assertEquals("标题A",node.path("history").path("runs").get(0).path("cases").get(0).path("titleSnapshot").asText());var b=empty();var dest=b.project;transfer.transfer(b.actor,dest,new FunctionalTransferService.ImportRequest(UUID.randomUUID().toString(),b.actor.userId(),snapshot));var copied=executions.listRuns(b.actor,dest,null).getFirst();assertEquals("标题A",executions.listRunCases(b.actor,dest,copied.id()).getFirst().title());
        ((ObjectNode)node.path("history").path("runs").get(0).path("cases").get(0)).remove("titleSnapshot");var legacy=json.treeToValue(node,FunctionalTransferService.Snapshot.class);var oldDest=empty();var legacyDest=oldDest.project;transfer.transfer(oldDest.actor,legacyDest,new FunctionalTransferService.ImportRequest(UUID.randomUUID().toString(),oldDest.actor.userId(),legacy));var cr=executions.listRunCases(oldDest.actor,legacyDest,executions.listRuns(oldDest.actor,legacyDest,null).getFirst().id()).getFirst();assertEquals("CURRENT_ASSET",json.valueToTree(cr).path("titleSource").asText());
        ((ObjectNode)node.path("history").path("runs").get(0).path("cases").get(0)).put("titleSnapshot"," ");var bad=json.treeToValue(node,FunctionalTransferService.Snapshot.class);var badTarget=empty();var badDest=badTarget.project;var before=counts();assertThrows(ResponseStatusException.class,()->transfer.transfer(badTarget.actor,badDest,new FunctionalTransferService.ImportRequest(UUID.randomUUID().toString(),badTarget.actor.userId(),bad)));assertEquals(before,counts());
        for(Object invalid:List.of(123,true,List.of(),Map.of())) { ((ObjectNode)node.path("history").path("runs").get(0).path("cases").get(0)).set("titleSnapshot",json.valueToTree(invalid));var bytes=json.writeValueAsBytes(Map.of("requestKey",UUID.randomUUID().toString(),"expectedUserId",badTarget.actor.userId(),"snapshot",node));assertEquals(400,mvc.perform(post("/api/v1/projects/"+badDest+"/functional/transfer").with(user(badTarget.actor)).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(bytes)).andReturn().getResponse().getStatus());assertEquals(before,counts());}
    }
    @Test void B07_syncPreservesSnapshotAndMissing()throws Exception {var a=fixture();run(a);rename(a);var item=sync.snapshot(a.actor,a.project,a.actor.userId()).items().getFirst();var b=fixture();sync.apply(b.actor,b.project,request(b,item));assertEquals("标题A",result(b,executions.listRuns(b.actor,b.project,null).getFirst()).title());var node=json.valueToTree(item);((ObjectNode)node.path("definition").path("cases").get(0)).remove("titleSnapshot");var legacy=json.treeToValue(node,FunctionalHistorySyncService.Item.class);var c=fixture();sync.apply(c.actor,c.project,request(c,legacy));assertEquals("CURRENT_ASSET",json.valueToTree(result(c,executions.listRuns(c.actor,c.project,null).getFirst())).path("titleSource").asText());((ObjectNode)node.path("definition").path("cases").get(0)).put("titleSnapshot"," ");var invalid=json.treeToValue(node,FunctionalHistorySyncService.Item.class);var before=counts();assertThrows(ResponseStatusException.class,()->sync.apply(c.actor,c.project,request(c,invalid)));assertEquals(before,counts());}
    @Test void B08_snapshotCannotBeOverwrittenOrRemoved()throws Exception {var f=fixture();run(f);var item=sync.snapshot(f.actor,f.project,f.actor.userId()).items().getFirst();for(boolean remove:List.of(false,true)){var node=json.valueToTree(item);var c=(ObjectNode)node.path("definition").path("cases").get(0);if(remove)c.remove("titleSnapshot");else c.put("titleSnapshot","伪造历史");var modified=json.treeToValue(node,FunctionalHistorySyncService.Item.class);var before=counts();assertEquals(409,assertThrows(ResponseStatusException.class,()->sync.apply(f.actor,f.project,request(f,modified))).getStatusCode().value());assertEquals(before,counts());}}
    @Test void B09_concurrentRenameAndRunAreConsistent()throws Exception {var f=fixture();var tx=new TransactionTemplate(transactions);try(var pool=Executors.newFixedThreadPool(2)){var locked=new CountDownLatch(1);var release=new CountDownLatch(1);var first=pool.submit(()->tx.execute(s->{jdbc.sql("SELECT id FROM project WHERE id=:p FOR UPDATE").param("p",f.project).query(String.class).single();rename(f);locked.countDown();try{assertTrue(release.await(10,TimeUnit.SECONDS));}catch(InterruptedException e){throw new IllegalStateException(e);}return null;}));assertTrue(locked.await(10,TimeUnit.SECONDS));var second=pool.submit(()->run(f));try{assertThrows(TimeoutException.class,()->second.get(200,TimeUnit.MILLISECONDS));}finally{release.countDown();}first.get(20,TimeUnit.SECONDS);var r=second.get(20,TimeUnit.SECONDS);assertEquals("标题B",result(f,r).title());assertEquals("步骤B",executions.listRunSteps(f.actor,f.project,result(f,r).id()).getFirst().stepText());}}
    @Test void B10_permissionAndFailedRunNoPartialWrites()throws Exception {var f=fixture();var other=fixture();var before=counts();assertEquals(403,mvc.perform(put(url(f)).with(user(other.actor)).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"planCode\":\"PLAN-1\",\"name\":\"x\"}")).andReturn().getResponse().getStatus());assertThrows(ResponseStatusException.class,()->executions.createRun(f.actor,f.project,f.plan.id(),"x".repeat(201)));assertEquals(before,counts());}
}
